import{o as e,c as t,a as p}from"./app.377163b2.js";const a='{"title":"预览&构建&部署","description":"","frontmatter":{},"headers":[{"level":2,"title":"通过可视化方式","slug":"通过可视化方式"},{"level":3,"title":"运行uni-app","slug":"运行uni-app"},{"level":3,"title":"打包uni-app","slug":"打包uni-app"},{"level":2,"title":"通过vue-cli命令行","slug":"通过vue-cli命令行"},{"level":3,"title":"环境安装","slug":"环境安装"},{"level":3,"title":"运行、发布uni-app","slug":"运行、发布uni-app"}],"relativePath":"guide/deploy.md","lastUpdated":1689321120063}',l={},i=p('<h1 id="预览-构建-部署"><a class="header-anchor" href="#预览-构建-部署" aria-hidden="true">#</a> 预览&amp;构建&amp;部署</h1><div class="tip custom-block"><p class="custom-block-title">前言</p><p>uni-app支持通过 <strong>可视化界面</strong> 、<strong>vue-cli命令行</strong> 两种方式快速创建项目</p><p>由于宋承昊的博客是开源项目，所以已经去除掉了项目中的 <a href="https://gitee.com/kevin_chou/qdpz/blob/develop/manifest.json" target="_blank" rel="noopener noreferrer">AppID</a>， 故无法打包小程序，如您需要打包请申请小程序AppID。</p></div><h2 id="通过可视化方式"><a class="header-anchor" href="#通过可视化方式" aria-hidden="true">#</a> 通过可视化方式</h2><p>开始之前，开发者需先下载安装如下工具：</p><ul><li>HBuilderX：<a href="https://www.dcloud.io/hbuilderx.html" target="_blank" rel="noopener noreferrer">官方IDE下载地址</a></li></ul><p>HBuilderX是通用的前端开发工具，但为uni-app做了特别强化</p><p>下载App开发版，可开箱即用；如下载标准版，在运行或发行uni-app时，会提示安装uni-app插件，插件下载完成后方可使用</p><h3 id="运行uni-app"><a class="header-anchor" href="#运行uni-app" aria-hidden="true">#</a> 运行uni-app</h3><ul><li><strong>浏览器运行</strong> ：进入hello-uniapp项目，点击工具栏的运行 -&gt; 运行到浏览器 -&gt; 选择浏览器，即可在浏览器里面体验uni-app 的 H5 版</li></ul><img src="https://bjetxgzv.cdn.bspapp.com/VKCEYUGU-uni-app-doc/1ad34710-4f1a-11eb-8ff1-d5dcf8779628.png" width="40%"><ul><li><strong>真机运行</strong> ：连接手机，开启USB调试，进入hello-uniapp项目，点击工具栏的运行 -&gt; 真机运行 -&gt; 选择运行的设备，即可在该设备里面体验uni-app</li></ul><img src="https://bjetxgzv.cdn.bspapp.com/VKCEYUGU-uni-app-doc/3a1faaf0-4f1a-11eb-b680-7980c8a877b8.png" width="40%"><p>如 <code>手机无法识别</code>，请点击菜单运行-运行到手机或模拟器-真机运行常见故障排查指南。 注意目前开发App也需要安装微信开发者工具</p><ul><li><strong>在微信开发者工具里运行</strong> ：进入hello-uniapp项目，点击工具栏的运行 -&gt; 运行到小程序模拟器 -&gt; 微信开发者工具，即可在微信开发者工具里面体验uni-app</li></ul><img src="https://bjetxgzv.cdn.bspapp.com/VKCEYUGU-uni-app-doc/d89fd6f0-4f1a-11eb-97b7-0dc4655d6e68.png" width="40%"><div class="warning custom-block"><p class="custom-block-title">注意事项</p><p>如果是第一次使用，需要先配置小程序ide的相关路径，才能运行成功。如下图，需在输入框输入微信开发者工具的安装路径。 若HBuilderX不能正常启动微信开发者工具，需要开发者手动启动，然后将uni-app生成小程序工程的路径拷贝到微信开发者工具里面，在HBuilderX里面开发，在微信开发者工具里面就可看到实时的效果。</p></div><p>uni-app默认把项目编译到根目录的unpackage目录</p><img src="https://bjetxgzv.cdn.bspapp.com/VKCEYUGU-uni-app-doc/a142b6a0-4f1a-11eb-8a36-ebb87efcf8c0.png" width="100%"><ul><li><strong>支付宝小程序开发者工具里运行</strong> ：进入hello-uniapp项目，点击工具栏的运行 -&gt; 运行到小程序模拟器 -&gt; 支付宝小程序开发者工具，即可在支付宝小程序开发者工具里面体验uni-app</li></ul><img src="https://bjetxgzv.cdn.bspapp.com/VKCEYUGU-uni-app-doc/fee90480-4f1a-11eb-bd01-97bc1429a9ff.png" width="40%"><ul><li>在 <strong><code>百度开发者工具</code>、<code>字节跳动开发者工具</code>、<code>快应用联盟</code>、<code>华为开发者工具</code>、<code>QQ小程序</code></strong>、开发工具里运行：内容同上，不再重复。</li></ul><div class="warning custom-block"><p class="custom-block-title">注意事项</p><ul><li>如果是第一次使用，需要配置开发工具的相关路径。点击工具栏的运行 -&gt; 运行到小程序模拟器 -&gt; 运行设置，配置相应小程序开发者工具的路径</li><li>支付宝/百度/字节跳动/360小程序工具，不支持直接指定项目启动并运行。因此开发工具启动后，请将 HBuilderX 控制台中提示的项目路径，在相应小程序开发者工具中打开</li><li>如果自动启动小程序开发工具失败，请手动启动小程序开发工具并将 HBuilderX 控制台提示的项目路径，打开项目</li></ul></div><h3 id="打包uni-app"><a class="header-anchor" href="#打包uni-app" aria-hidden="true">#</a> 打包uni-app</h3><ul><li><strong>打包为原生App：</strong> 在HBuilderX工具栏，点击发行，选择原生app-云端打包，如下图：</li></ul><img src="https://bjetxgzv.cdn.bspapp.com/VKCEYUGU-uni-app-doc/b8332fd0-4f37-11eb-8ff1-d5dcf8779628.png" width="24%"><p>出现如下界面，点击打包即可</p><img src="https://bjetxgzv.cdn.bspapp.com/VKCEYUGU-dc-site/001a20b0-d85a-11ea-81ea-f115fe74321c.png" width="40%"><ul><li><strong>打包为H5：</strong> 在 manifest.json 的可视化界面，进行如下配置（发行在网站根目录可不配置应用基本路径），此时发行网站路径是 <a href="http://www.xxx.com/h5%EF%BC%9A" target="_blank" rel="noopener noreferrer">www.xxx.com/h5：</a></li></ul><img src="https://bjetxgzv.cdn.bspapp.com/VKCEYUGU-uni-app-doc/bf90de30-4f37-11eb-8ff1-d5dcf8779628.png" width="40%"><p>在HBuilderX工具栏，点击发行，选择网站-H5手机版，如下图，点击即可生成 H5 的相关资源文件，保存于 unpackage 目录</p><img src="https://bjetxgzv.cdn.bspapp.com/VKCEYUGU-uni-app-doc/b7391860-4f37-11eb-8a36-ebb87efcf8c0.png" width="24%"><div class="warning custom-block"><p class="custom-block-title">注意事项</p><ul><li>history 模式发行需要后台配置支持，详见：<a href="https://router.vuejs.org/zh/guide/essentials/history-mode.html#%E5%90%8E%E7%AB%AF%E9%85%8D%E7%BD%AE%E4%BE%8B%E5%AD%90" target="_blank" rel="noopener noreferrer">history模式的后端配置</a></li><li>打包部署后，在服务器上开启 gzip 可以进一步压缩文件。具体的配置，可以参考网上的分享：<a href="https://juejin.im/post/5af003286fb9a07aac24611b" target="_blank" rel="noopener noreferrer">https://juejin.im/post/5af003286fb9a07aac24611b</a></li></ul></div><ul><li><strong>打包为微信小程序：</strong></li></ul><ol><li>申请微信小程序AppID，参考：<a href="https://developers.weixin.qq.com/miniprogram/dev/framework/quickstart/getstart.html#%E7%94%B3%E8%AF%B7%E5%B8%90%E5%8F%B7" target="_blank" rel="noopener noreferrer">微信教程</a></li><li>在HBuilderX中顶部菜单依次点击 &quot;发行&quot; =&gt; &quot;小程序-微信&quot;，输入小程序名称和appid点击发行即可在 <strong><code>unpackage/dist/build/mp-weixin</code></strong> 生成微信小程序项目代码</li></ol><img src="https://bjetxgzv.cdn.bspapp.com/VKCEYUGU-uni-app-doc/b36294f0-4f37-11eb-8a36-ebb87efcf8c0.png" width="50%"><ol start="3"><li>在微信小程序开发者工具中，导入生成的微信小程序项目，测试项目代码运行正常后，点击“上传”按钮，之后按照 “提交审核” =&gt; “发布” 小程序标准流程，逐步操作即可，详细查看：<a href="https://developers.weixin.qq.com/miniprogram/dev/framework/quickstart/release.html#%E5%8F%91%E5%B8%83%E4%B8%8A%E7%BA%BF" target="_blank" rel="noopener noreferrer">微信官方教程</a>。</li></ol><ul><li>在 <strong><code>百度开发者工具</code>、<code>字节跳动开发者工具</code>、<code>快应用联盟</code>、<code>华为开发者工具</code>、<code>QQ小程序</code></strong> 发布：内容基本同上，不再重复。</li></ul><h2 id="通过vue-cli命令行"><a class="header-anchor" href="#通过vue-cli命令行" aria-hidden="true">#</a> 通过vue-cli命令行</h2><p><strong>除了HBuilderX可视化界面，也可以使用 <code>cli</code> 脚手架，可以通过 <code>vue-cli</code> 创建 <code>uni-app</code> 项目</strong></p><h3 id="环境安装"><a class="header-anchor" href="#环境安装" aria-hidden="true">#</a> 环境安装</h3><p>全局安装vue-cli</p><div class="language-"><pre><code>npm install -g @vue/cli\n</code></pre></div><h3 id="运行、发布uni-app"><a class="header-anchor" href="#运行、发布uni-app" aria-hidden="true">#</a> 运行、发布uni-app</h3><div class="language-"><pre><code>npm run dev:%PLATFORM%\nnpm run build:%PLATFORM%\n</code></pre></div><p><code>%PLATFORM%</code> 可取值如下：</p><table><thead><tr><th style="text-align:center;"><strong>值</strong></th><th style="text-align:center;"><strong>平台</strong></th></tr></thead><tbody><tr><td style="text-align:center;">app-plus</td><td style="text-align:center;">app平台生成打包资源（支持npm run build:app-plus，可用于持续集成。不支持run，运行调试仍需在HBuilderX中操作）</td></tr><tr><td style="text-align:center;">h5</td><td style="text-align:center;">H5</td></tr><tr><td style="text-align:center;">mp-alipay</td><td style="text-align:center;">支付宝小程序</td></tr><tr><td style="text-align:center;">mp-baidu</td><td style="text-align:center;">百度小程序</td></tr><tr><td style="text-align:center;">mp-weixin</td><td style="text-align:center;">微信小程序</td></tr><tr><td style="text-align:center;">mp-toutiao</td><td style="text-align:center;">字节跳动小程序</td></tr><tr><td style="text-align:center;">mp-qq</td><td style="text-align:center;">QQ 小程序</td></tr><tr><td style="text-align:center;">mp-360</td><td style="text-align:center;">360 小程序</td></tr><tr><td style="text-align:center;">mp-kuaishou</td><td style="text-align:center;">快手小程序</td></tr><tr><td style="text-align:center;">quickapp-webview</td><td style="text-align:center;">快应用(webview)</td></tr><tr><td style="text-align:center;">quickapp-webview-union</td><td style="text-align:center;">快应用联盟</td></tr><tr><td style="text-align:center;">quickapp-webview-huawei</td><td style="text-align:center;">快应用华为</td></tr></tbody></table><p>可以自定义更多条件编译平台，比如钉钉小程序，参考<a href="https://uniapp.dcloud.io/collocation/package" target="_blank" rel="noopener noreferrer">package.json文档</a>。</p><h4 id="运行并发布快应用："><a class="header-anchor" href="#运行并发布快应用：" aria-hidden="true">#</a> 运行并发布快应用：</h4><p>快应用有两种开发方式，uni-app均支持：</p><ul><li>类小程序webview渲染方式：<a href="https://ask.dcloud.net.cn/article/37182" target="_blank" rel="noopener noreferrer">https://ask.dcloud.net.cn/article/37182</a></li><li>原生渲染方式：<a href="https://ask.dcloud.net.cn/article/37145" target="_blank" rel="noopener noreferrer">https://ask.dcloud.net.cn/article/37145</a></li></ul><div class="warning custom-block"><p class="custom-block-title">注意事项</p><ul><li><p>目前使用<code>npm run build:app-plus</code>会在 <code>/dist/build/app-plus</code> 下生成app打包资源。如需制作wgt包，将 <code>app-plus</code> 中的文件压缩成zip（注意：不要包含 <code>app-plus目录</code> ），再重命名为 <code>${appid}.wgt</code> ， <code>appid</code> 为 <code>manifest.json</code> 文件中的 <code>appid</code>。</p></li><li><p>dev 模式编译出的各平台代码存放于根目录下的 <code>/dist/dev/</code> 目录，打开各平台开发工具选择对应平台目录即可进行预览（h5 平台不会在此目录，存在于缓存中）；</p></li><li><p>build 模式编译出的各平台代码存放于根目录下的 <code>/dist/build/</code> 目录，发布时选择此目录进行发布；</p></li><li><p>dev 和 build 模式的区别：</p><p>1.dev 模式有 SourceMap 可以方便的进行断点调试；</p><p>2.build 模式会将代码进行压缩，体积更小更适合发布为正式版应用；</p><p>3.进行 环境判断 时，dev 模式 process.<wbr>env.NODE_ENV 的值为 development，build 模式 process.<wbr>env.NODE_ENV 的值为 production。</p></li></ul></div>',51);l.render=function(p,a,l,r,d,n){return e(),t("div",null,[i])};export default l;export{a as __pageData};
